        "code": "def main(url_arg: str):
	import requests
	import json
	# Parse GitHub URL to get owner and repo
	parts = url_arg.rstrip('/').split('/')
	owner = parts[-2]
	repo = parts[-1]
	api_url = f'https://api.github.com/repos/{owner}/{repo}/contents'

	def build_tree(path='', prefix='', is_last=True):
	    url = api_url if not path else f'{api_url}/{path}'
	    response = requests.get(url)
	    if response.status_code == 200:
	        items = response.json()
	        tree_str = ''

	        for i, item in enumerate(items):
	            connector = '└─ ' if i == len(items) - 1 else '├─ '
	            current_prefix = prefix + connector

	            if item['type'] == 'file':
	                tree_str += f'{current_prefix}{item["name"]}\n'
	            elif item['type'] == 'dir':
	                tree_str += f'{current_prefix}{item["name"]}/\n'
	                # Recursively build subtree
	                new_prefix = prefix + ('    ' if i == len(items) - 1 else '│   ')
	                subtree = build_tree(item['path'], new_prefix, i == len(items) - 1)
	                tree_str += subtree

	        return tree_str
	    else:
	        return ''

	file_structure_tree = build_tree()
	return {"file_structure": file_structure_tree}"
